Algorithm Ficha
  Switch parseJson('{"nombre": "Ana", "edad": 15}') Do
    Success(ficha):
      Switch ficha.field("edad") Do
        Some(edad): Write "edad: ", jsonText(edad);
        None: Write "sin edad";
      EndSwitch
    Failure(problema): Write problema.code;
  EndSwitch
EndAlgorithm

Function par <- ParJson(nombre As String, stock As Integer)
  Define par As String;
  par <- '"' + nombre + '": ' + toText(stock);
EndFunction

Function texto <- InventarioJson()
  Define texto As String;
  texto <- "{" + ParJson("jugo", 10) + ", " + ParJson("sandwich", 5) + ", " + ParJson("alfajor", 8) + ", " + ParJson("agua", 12) + ", " + ParJson("fruta", 6) + "}";
EndFunction

Algorithm Exportar
  Define texto As String <- InventarioJson();
  Write texto;
  Switch parseJson(texto) Do
    Success(inventario): Write "Válido: ", inventario.length(), " productos";
    Failure(problema): Write "Inválido: ", problema.code;
  EndSwitch
EndAlgorithm

Algorithm Roto
  Switch parseJson('{"jugo": 10,}') Do
    Success(inventario): Write jsonText(inventario);
    Failure(problema): Write problema.code, " en ", problema.jsonLine, ":", problema.jsonColumn;
  EndSwitch
EndAlgorithm
